void dei_ask_trace_frame( void )
{
    TRACE_DEI_ASK("\n\r[LIB.DEI_ASK] - frame received\n\r");
    TRACE_DEI_ASK(" - fixed portion [%01x %08x]\n\r",(UInt32)(dei_ask.data_fix.data>>32),(UInt32)(dei_ask.data_fix.data>>0));
    TRACE_DEI_ASK("     * Repeat [%02x]\n\r",dei_ask.data_fix.bits.repeat);
    TRACE_DEI_ASK("     * Vlow   [%02x]\n\r",dei_ask.data_fix.bits.v_low );
    TRACE_DEI_ASK("     * Button [%02x]\n\r",dei_ask.data_fix.bits.button);
    TRACE_DEI_ASK("     * SN     [%04x]\n\r",dei_ask.data_fix.bits.sn    );
    
    TRACE_DEI_ASK("\n\r - encrypted portion [%08x]\n\r",(UInt32)(dei_ask.data_enc.data>>0));
    TRACE_DEI_ASK("     * Sync count [%04x]\n\r",dei_ask.data_enc.bits.sc    );
    TRACE_DEI_ASK("     * DISC       [%04x]\n\r",dei_ask.data_enc.bits.disc  );
    TRACE_DEI_ASK("     * OVR        [%02x]\n\r",dei_ask.data_enc.bits.ovr   );
    TRACE_DEI_ASK("     * Button     [%02x]\n\r",dei_ask.data_enc.bits.button);            
}

